<?php

namespace AppBundle\Entity\Repository;

use AppBundle\Repository\Contract\AccessRuleRepositoryInterface;
use Doctrine\ORM\EntityRepository;

/**
 * AccessRuleRepository
 *
 * This class was generated by the PhpStorm "Php Annotations" Plugin. Add your own custom
 * repository methods below.
 */
class AccessRuleRepository extends EntityRepository implements AccessRuleRepositoryInterface
{
    /**
     * @return AccessRule[]
     */
    public function findAll(): array
    {
        return $this
            ->createQueryBuilder('rule')
            ->orderBy('rule.resource')
            ->addOrderBy('rule.method')
            ->addOrderBy('rule.name')
            ->getQuery()
            ->getResult();
    }

    /**
     * @param string $resource
     * @param string $method
     * @return AccessRule[]
     */
    public function findByResourceAndMethod(string $resource, string $method): array
    {
        return $this
            ->createQueryBuilder('accessRule')
            ->andWhere('accessRule.resource = :resource')
            ->setParameter('resource', $resource)
            ->andWhere('accessRule.method = :method')
            ->setParameter('method', $method)
            ->getQuery()
            ->getResult();
    }

    /**
     * @return AccessRule[]
     */
    public function findRoutingRules(): array
    {
        return $this->findRules(true);
    }

    /**
     * @return AccessRule[]
     */
    public function findCustomRules(): array
    {
        return $this->findRules(false);
    }

    private function findRules(bool $isRouting)
    {
        return $this
            ->createQueryBuilder('rule')
            ->where('rule.isRoutingRule = :isRouting')
            ->setParameter('isRouting', $isRouting)
            ->orderBy('rule.resource')
            ->addOrderBy('rule.method')
            ->addOrderBy('rule.name')
            ->getQuery()
            ->getResult();
    }
}
